#include <stdio.h>int main(){    int a;    scanf("%d",&a);    while(a--){      float n;            scanf("%f",&n);      int f=0;            for(float i=0;i<=n/2;i++){        for(float j=0;j<=n/4;j++){          if((2*j)+i==(n/2)){            f++;          }        }      }      printf("%d\n",f);    }}